async function chargerSecurise(route, annuler) {
  const controleur = new AbortController();
  if (annuler) { controleur.abort(); }
  let r;
  try { r = await fetch("/api-pedagogique/v1/" + route, {signal:controleur.signal}); }
  catch (erreur) { return {etat:erreur.name === "AbortError" ? "annulé" : "réseau",statut:null}; }
  if (!r.ok) { return {etat:"http",statut:r.status}; }
  try { await r.json(); } catch (erreur) { return {etat:"json",statut:r.status}; }
  return {etat:"prêt",statut:r.status};
}

