async function parcours(route, ville, atelierId, nom, annuler) {
  const controleur = new AbortController();
  if (annuler) { controleur.abort(); }
  const url = new URL("/api-pedagogique/v1/" + route, "https://exemple.invalid");
  if (route === "ateliers") { url.searchParams.set("ville", ville); }
  let r;
  try { r = await fetch(url.pathname + url.search, {signal:controleur.signal}); }
  catch (erreur) { return {etat:erreur.name === "AbortError" ? "annulé" : "réseau",statut:null,nom:null}; }
  if (!r.ok) { return {etat:"http",statut:r.status,nom:null}; }
  let ateliers;
  try { ateliers = await r.json(); }
  catch (erreur) { return {etat:"json",statut:r.status,nom:null}; }
  let choisi = null;
  for (const atelier of ateliers) { if (atelier.id === atelierId) { choisi = atelier; } }
  if (choisi === null) { return {etat:"absent",statut:200,nom:null}; }
  if (choisi.places === 0) { return {etat:"complet",statut:200,nom:null}; }
  let inscription;
  try { inscription = await fetch("/api-pedagogique/v1/inscriptions", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({atelierId:atelierId,nom:nom})}); }
  catch (erreur) { return {etat:"réseau",statut:null,nom:null}; }
  let corps;
  try { corps = await inscription.json(); }
  catch (erreur) { return {etat:"json",statut:inscription.status,nom:null}; }
  if (!inscription.ok) { return {etat:"refusée",statut:inscription.status,nom:null}; }
  return {etat:"confirmation-fictive",statut:inscription.status,nom:corps.nom};
}

